function D = ttSimulateDataset(varargin)
%TTSIMULATEDATASET  Synthetic dataset: animals that learn a delay through a training schedule, generated by a policy model.
%
%   D = ttSimulateDataset()
%   D = ttSimulateDataset('nAnimals', 4, 'seed', 1, 'model', ttModel(...), 'theta', @(group) ..., 'schedule', sched)
%
%   Each animal runs the schedule: cue-association sessions (delay 0.1 s), delay-training sessions
%   whose delay rises in within-session steps towards the target, fixed-delay sessions at the
%   target, and switching sessions that alternate two delays in blocks of random length. Lick times
%   come from ttSimulate with the generating model; the model's state carries over within a session
%   and restarts at every session. Animals belong to two groups ('A', 'B') that differ in the
%   generating parameters returned by 'theta' (default: group B learns at half the rate).
%
%   The default generating model is the threshold-tracking actor with history on the log-normal +
%   exponential policy. D has the layout of ttBuildDataset; D.truth holds the generating
%   parameters per animal.
p = inputParser;
p.addParameter('nAnimals', 4, @isnumeric); p.addParameter('seed', 1, @isnumeric);
p.addParameter('model', ttModel('family', 'lnexp', 'timed', 'historyLearn', 'early', 'fixed', 'rule', 'threshold'), @isstruct);
p.addParameter('theta', [], @(x) isa(x, 'function_handle'));
p.addParameter('schedule', struct('cue', 2, 'delay', 8, 'fixed', 3, 'switching', 3, 'target', 1.8, 'switchDelays', [1.0 3.0], 'trialsPerSession', 500), @isstruct);
p.parse(varargin{:}); o = p.Results;
model = o.model; sc = o.schedule; rs = RandStream('mt19937ar', 'Seed', o.seed);
if isempty(o.theta)
    o.theta = @(group) defaultTheta(model, group);
end
trials = {}; sessions = {}; truth = {};
for a = 1:o.nAnimals
    animal = sprintf('SIM%02d', a); if mod(a, 2) == 0, group = 'B'; else, group = 'A'; end
    th = o.theta(group); truth{end+1} = [table(string(animal), string(group), 'VariableNames', {'animal', 'group'}), array2table(th(:)', 'VariableNames', model.names)]; %#ok<AGROW>
    k = 0; plan = {};
    for i = 1:sc.cue, plan{end+1} = 0.1 * ones(sc.trialsPerSession, 1); end %#ok<AGROW>
    for i = 1:sc.delay
        lo = sc.target * (i - 1) / sc.delay; hi = sc.target * i / sc.delay; steps = max(2, round(hi * 10 - lo * 10));
        lv = linspace(max(lo, 0.1), max(hi, 0.2), steps); plan{end+1} = reshape(repmat(lv, ceil(sc.trialsPerSession / steps), 1), [], 1); %#ok<AGROW>
        plan{end} = plan{end}(1:sc.trialsPerSession);
    end
    for i = 1:sc.fixed, plan{end+1} = sc.target * ones(sc.trialsPerSession, 1); end %#ok<AGROW>
    for i = 1:sc.switching
        d = []; cur = 1 + (rand(rs) > 0.5);
        while numel(d) < sc.trialsPerSession, len = 40 + randi(rs, 80); d = [d; sc.switchDelays(cur) * ones(len, 1)]; cur = 3 - cur; end %#ok<AGROW>
        plan{end+1} = d(1:sc.trialsPerSession); %#ok<AGROW>
    end
    for s = 1:numel(plan)
        k = k + 1; B = struct('delay', plan{s}); Ssim = ttSimulate(th, B, model, o.seed * 1000 + a * 100 + s);
        n = numel(Ssim.tau); sid = sprintf('%s_s%02d', animal, k); dc = Ssim.delay;
        T = table(repmat(string(animal), n, 1), repmat(string(sid), n, 1), (1:n)', Ssim.tau, double(Ssim.R == 0), Ssim.R == 1, dc, true(n, 1), false(n, 1), repmat(k, n, 1), ...
            'VariableNames', {'animal', 'session', 'trialNum', 'lickTime', 'outcome', 'rewarded', 'delay', 'cued', 'noCue', 'sessionIndex'});
        st = ttClassifyStage(dc, n); T.stage = repmat(st, n, 1); trials{end+1} = T; %#ok<AGROW>
        lv = unique(round(dc, 2));
        sessions{end+1} = table(string(animal), string(sid), k, NaT, n, n, sum(Ssim.R), 0, string(mat2str(lv', 3)), mean(dc), st, string(group), ...
            'VariableNames', {'animal', 'session', 'sessionIndex', 'date', 'nTrials', 'nCued', 'nRewarded', 'nNoCue', 'delayLevels', 'delayMean', 'stage', 'group'}); %#ok<AGROW>
    end
end
D = struct('trials', vertcat(trials{:}), 'sessions', vertcat(sessions{:}), 'truth', vertcat(truth{:}), 'model', model);
D = ttAssignPhases(D);
end
function th = defaultTheta(model, group)
th = ttPrior(model).mu;
th(model.idx.b_z) = log(0.25); th(model.idx.sigma) = 0.3;
if isfield(model.idx, 'b_logr'), th(model.idx.b_logr) = log(2); end; if isfield(model.idx, 'b_ell'), th(model.idx.b_ell) = log(0.1 / 0.9); end
if isfield(model.idx, 'w_z_tau1'), th(model.idx.w_z_tau1) = 0.2; end; if isfield(model.idx, 'w_z_R1'), th(model.idx.w_z_R1) = -0.15; end
if isfield(model.idx, 'alpha_up'), th(model.idx.alpha_up) = 0.08; end; if isfield(model.idx, 'alpha_z'), th(model.idx.alpha_z) = 0.05; end
if isfield(model.idx, 'm_z'), th(model.idx.m_z) = 0.2; end
if strcmp(group, 'B'), for nm = {'alpha_up', 'alpha_z'}, if isfield(model.idx, nm{1}), th(model.idx.(nm{1})) = th(model.idx.(nm{1})) / 2; end, end, end
end
